#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> np;
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    // Place elements from left: put element (t+1) at position t
    for (int t = 0; t < n - 2 && ops.size() < (size_t)n; t++) {
        int pos = -1;
        for (int i = t; i < n; i++) if (p[i] == t + 1) { pos = i; break; }
        if (pos == t) continue;

        // Move element to position n-1 first (if not already there)
        if (pos != n - 1) {
            // x = pos+1, y = n-1-pos: x+y = pos+1+n-1-pos = n. Need x+y < n. 
            // So use x = pos, y = n-1-pos if pos > 0 and n-1-pos > 0 and pos + n-1-pos = n-1 < n. Good if middle >= 1: n - pos - (n-1-pos) = 1. OK.
            if (pos > 0 && n - 1 - pos > 0) {
                ops.push_back({pos, n - 1 - pos});
                apply_op(p, pos, n - 1 - pos);
                // element was at pos, now at end of suffix = position (n-1-pos)-1 = n-pos-2... 
                // Actually suffix starts at pos+1 wait no. x=pos, so prefix=[0..pos-1], middle=[pos..pos], suffix=[pos+1..n-1]
                // result: suffix + middle + prefix. Element was at pos = middle[0] -> position n-1-pos
            }
            pos = -1;
            for (int i = t; i < n; i++) if (p[i] == t + 1) { pos = i; break; }
            if (pos == t) continue;
            if (pos != n - 1 && pos > 0) {
                ops.push_back({pos, n - 1 - pos});
                apply_op(p, pos, n - 1 - pos);
                pos = -1;
                for (int i = t; i < n; i++) if (p[i] == t + 1) { pos = i; break; }
                if (pos == t) continue;
            }
        }
        // Now move from n-1 to t: x = n-1-t, y=1. Need n-1-t+1<n => t>0. Middle size=n-n+t=t>=1 when t>0
        if (pos == n - 1 && t > 0 && n - 1 - t > 0) {
            ops.push_back({n - 1 - t, 1});
            apply_op(p, n - 1 - t, 1);
        } else if (pos == n - 1 && t == 0 && n > 2) {
            ops.push_back({1, 1});
            apply_op(p, 1, 1);
        }
    }
    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
